intentos.respuesta_cruda:
{
  "sql": "SELECT t.categoria_ingles, ROUND(100.0 * SUM(t.flete_total) / SUM(t.ingresos), 2) AS porcentaje_flete FROM ( SELECT COALESCE(pc.product_category_name_english, 'sin_categoria') AS categoria_ingles, SUM(oi.price) AS ingresos, SUM(oi.freight_value) AS flete_total FROM order_items oi JOIN products p ON oi.product_id = p.product_id LEFT JOIN product_category_translation pc ON p.product_category_name = pc.product_category_name JOIN vw_pedidos_validos v ON oi.order_id = v.order_id GROUP BY categoria_ingles HAVING SUM(oi.price) >= 5000 ) t ORDER BY porcentaje_flete DESC LIMIT 3"
}
